/// A timed-out run kills the whole spawned subtree, not just the direct child.
///
/// Regression guard for SMA-613. On unix this guards the `process_group(0)` +
/// group `SIGSTOP`, then `SIGKILL`, path (SMA-710): the `alive` sentinel catches
/// a survivor that runs, and the stdout marker catches one that stays stopped.
/// On Windows it guards the Job Object kill that replaced a bare
/// `TerminateProcess` against `cmd.exe`, which left every grandchild running to
/// completion.
#[tokio::test]
async fn timeout_kills_the_whole_subtree() {
    let tmp = tempfile::tempdir().unwrap();
    let script_path = tmp.path().join(GRANDCHILD_SCRIPT_NAME);

    // `spawns_grandchild`'s Windows arm cannot quote `script_path` (see its doc
    // comment: any literal `"` is mangled by std's argument escaping before
    // `cmd.exe` ever sees it), so a space anywhere in the temp path would make
    // this test fail its positive control for a reason that has nothing to do
    // with the subtree kill. `windows-latest`'s `TEMP` is the 8.3
    // `C:\Users\RUNNER~1\...` form and `tempfile` adds no spaces, so this never
    // triggers in CI — it only guards a dev machine with a spacey `%TEMP%`.
    #[cfg(windows)]
    if script_path.display().to_string().contains(' ') {
        eprintln!(
            "SKIP timeout_kills_the_whole_subtree: script path {} contains a space; \
             the nested `cmd /C` invocation cannot accept a quoted path on Windows \
             (see `spawns_grandchild`'s doc comment), so this test cannot run from a \
             TEMP directory with a space in it",
            script_path.display()
        );
        return;
    }

    let started_path = tmp.path().join("started");
    let alive_path = tmp.path().join("alive");
    std::fs::write(&script_path, grandchild_script(&started_path, &alive_path)).unwrap();

    // 1s, not the 200ms used above: the `started` positive control must be
    // written before the kill lands, and 1s is generous margin for process
    // launch on a loaded CI runner.
    let backend = HostBackend::builder(Sandbox::open(tmp.path()).unwrap())
        .timeout(Duration::from_secs(1))
        .build();

    // Failure case is ~6s (1s timeout + the 5s GRACE reader drain, because a
    // surviving grandchild holds the inherited pipe write end) plus the 6s wait
    // below. 30s leaves headroom without masking a real hang.
    let out = tokio::time::timeout(
        Duration::from_secs(30),
        backend.run(ExecRequest::new(spawns_grandchild(&script_path))),
    )
    .await
    .expect("run must return promptly, not hang")
    .unwrap();

    assert!(
        out.timed_out,
        "the command must outlive the 1s timeout; stdout={:?} stderr={:?}",
        out.stdout, out.stderr
    );

    // Wait past the moment a surviving grandchild would have written `alive`.
    tokio::time::sleep(Duration::from_secs(6)).await;

    assert!(
        started_path.exists(),
        "positive control failed: the grandchild never ran, so the `alive` \
         assertion below would have passed for free; stdout={:?} stderr={:?}",
        out.stdout,
        out.stderr
    );
    assert!(
        !alive_path.exists(),
        "the grandchild outlived the timeout: the subtree was not killed; \
         stdout={:?} stderr={:?}",
        out.stdout,
        out.stderr
    );

